package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import android.view.inspector.WindowInspector;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;

/** Actual themed controls and isolated saved plans; no real reminder, alarm or recording output. */
public class PlanPickerFlowTest {
    final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice device=UiDevice.getInstance(i);PlanActivity activity;
    UiObject2 object(String label)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(label)),1000);if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().description(label));found=device.wait(Until.findObject(By.desc(label)),4000);}assertNotNull(label,found);return found;}
    void click(String label)throws Exception{UiObject2 found=device.findObject(By.text(label));if(found==null){new UiScrollable(new UiSelector().scrollable(true)).scrollIntoView(new UiSelector().text(label));found=device.findObject(By.text(label));}assertNotNull(label,found);found.click();device.waitForIdle();}
    void launch()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(PlanActivity.class.getName(),null,false);try{c.startActivity(RecordUi.intent(c,PlanActivity.class).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(PlanActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Sleep goals")),5000));assertTrue(device.wait(Until.gone(By.text("Loading recorded bedtimes…")),5000));device.waitForIdle();}
    void recreate()throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(PlanActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(PlanActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}device.waitForIdle();}
    void capture(String name)throws Exception{View[] owner={null};CountDownLatch frame=new CountDownLatch(1);long until=SystemClock.elapsedRealtime()+5000;while(owner[0]==null&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{for(View root:WindowInspector.getGlobalWindowViews())if(root.hasWindowFocus()&&root.isAttachedToWindow()&&root.isLaidOut()&&root.getWidth()>0&&root.getHeight()>0&&root.isHardwareAccelerated()){owner[0]=root;root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();break;}});if(owner[0]==null)SystemClock.sleep(50);}assertNotNull("Focused activity or picker window",owner[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();i.runOnMainSync(()->assertTrue("Same visible picker frame",owner[0].hasWindowFocus()&&owner[0].isAttachedToWindow()));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"plan-picker-"+name+".png")));}
    @Test public void pendingTimeDurationChoicesRecreateCancelAndPersistOnlyOnSave()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));
        String name="sleepwell-plan-picker-"+UUID.randomUUID();SharedPreferences isolated=c.getSharedPreferences(name,Context.MODE_PRIVATE);assertTrue(isolated.edit().putInt("goal",480).putInt("bedtime",1350).putInt("wakeTime",390).putLong("planRevision",10).commit());Map<String,?> personal=new HashMap<>(Prefs.of(c).getAll());Records.Factory priorRecords=Records.factory;SleepPlans.Factory priorPlans=SleepPlans.factory;SleepPlans.Reminder priorReminder=SleepPlans.reminders;AtomicInteger delivered=new AtomicInteger();List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){owned.add(a);assertTrue(a instanceof PlanActivity||a instanceof MainActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
        try{
            Records.factory=context->new Store(context,name+".db");SleepPlans.factory=context->isolated;SleepPlans.reminders=context->delivered.incrementAndGet();launch();
            object("Change planned bedtime").click();assertTrue(device.wait(Until.hasObject(By.desc("Hour")),4000));capture("time");object("Hour").setText("09");object("Minute").setText("15");object("PM").click();recreate();assertEquals("09",object("Hour").getText());assertEquals("15",object("Minute").getText());assertTrue(object("PM").isSelected());capture("time-recreated");click("Cancel");assertEquals(1350,SleepPlans.load(c).bedtime);
            object("Change planned bedtime").click();object("Hour").setText("08");object("Minute").setText("20");object("PM").click();click("Use time");assertEquals(1350,SleepPlans.load(c).bedtime);
            object("Sleep duration goal 8 h").click();capture("duration");object("Duration hours").setText("00");object("Duration minutes").setText("00");click("Use duration");assertTrue(device.wait(Until.hasObject(By.text("Choose 20 min to 13 h 30 min.")),3000));capture("duration-invalid");object("Duration hours").setText("08");object("Duration minutes").setText("45");recreate();assertEquals("08",object("Duration hours").getText());assertEquals("45",object("Duration minutes").getText());capture("duration-recreated");click("Use duration");assertNotNull(object("Sleep duration goal 8 h 45 min"));assertEquals(480,SleepPlans.load(c).goal);
            click("Reminder");capture("reminder");object("60 min before").click();click("Wind-down");object("90 min before").click();recreate();assertNotNull(object("Sleep duration goal 8 h 45 min"));assertEquals(0,delivered.get());click("Save sleep plan");assertTrue(device.wait(Until.hasObject(By.text("Tonight")),5000));PlanOperations.drain(10000);SleepPlan saved=SleepPlans.load(c);assertEquals(525,saved.goal);assertEquals(1175,saved.bedtime);assertEquals(260,saved.wake);assertEquals(90,saved.windDown);assertTrue(saved.reminder);assertEquals(60,saved.reminderAdvance);assertEquals(1,delivered.get());
            launch();assertNotNull(object("Sleep duration goal 8 h 45 min"));capture("reopened");object("Sleep duration goal 8 h 45 min").click();object("Duration hours").setText("09");click("Cancel");assertNotNull(object("Sleep duration goal 8 h 45 min"));assertEquals(525,SleepPlans.load(c).goal);assertEquals(personal,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"plan-picker-failure.png"));device.dumpWindowHierarchy(new File(folder,"plan-picker-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{boolean drained=false;try{PlanOperations.drain(10000);i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));for(Activity a:owned)if(a instanceof PlanActivity)((PlanActivity)a).awaitReaders(5000);drained=true;assertEquals(personal,Prefs.of(c).getAll());}finally{app.unregisterActivityLifecycleCallbacks(callbacks);Records.factory=priorRecords;SleepPlans.factory=priorPlans;SleepPlans.reminders=priorReminder;if(drained){c.deleteDatabase(name+".db");c.deleteSharedPreferences(name);}}}
    }
}
